  1→import { Screen } from "@prototyp/skeletor";
  2→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
  3→import { Membership, type RoomInfo } from "@unomed/react-native-matrix-sdk";
  4→import { MatrixService } from "modules/matrix-client/services";
  5→import { useRoomInitialization } from "modules/timeline/hooks";
  6→import { useEffect, useMemo, useState } from "react";
  7→import { useSafeAreaInsets } from "react-native-safe-area-context";
