 11→export const Room: React.FC<NativeStackScreenProps<Routes, "room">> = ({
 12→  route,
 13→  navigation,
 14→}) => {
 15→  const { roomId } = route.params;
 16→  const client = MatrixService.instance;
 17→  const room = useMemo(() => client?.getRoom(roomId), [client, roomId]);
 18→  const insets = useSafeAreaInsets();
 19→  const hasActiveCall = useMemo(() => room?.hasActiveRoomCall(), [room]);
 20→  const [roomInfo, setRoomInfo] = useState<RoomInfo | undefined>(undefined);
 21→  const [isInviteAccepted, setIsInviteAccepted] = useState(false);
 22→  const isRoomInvite = useMemo(() => {
 23→    return roomInfo?.membership === Membership.Invited && !isInviteAccepted;
 24→  }, [roomInfo, isInviteAccepted]);
 25→
 26→  const { isMembersLoading, roomMembers, hasNoCallOption } =
 27→    useRoomInitialization({ room });
 28→
 29→  useEffect(() => {
 30→    room?.roomInfo().then(setRoomInfo).catch(console.error);
 31→  }, [room]);
 32→
 33→  const handleStartCall = () => {
 34→    if (!client || !room) {
 35→      console.error("Client or room not available");
 36→      return;
 37→    }
 38→
 39→    navigation.navigate("elementCall", {
 40→      roomId,
 41→      roomName: room.displayName(),
 42→    });
 43→  };
 44→
 45→  const handleInviteAccepted = () => {
 46→    setIsInviteAccepted(true);
 47→  };
 48→
 49→  const handleInviteDeclined = () => {
 50→    navigation.goBack();
 51→  };
 52→
 53→  const handleRoomDetails = () => {
 54→    if (isRoomInvite || !room) return;
 55→    navigation.navigate("roomDetails", { room });
 56→  };
 57→
 58→  if (!room) return null;
 59→
 60→  if (!roomInfo) {
 61→    return (
 62→      <Screen hideTopSafeArea scrollable={false}>
 63→        <RoomHeader
 64→          room={room}
 65→          isMembersLoading={isMembersLoading}
 66→          roomMembers={roomMembers}
 67→          hasActiveCall={false}
 68→          hasNoCallOption
 69→          topInset={insets.top}
 70→          onBack={() => navigation.goBack()}
 71→        />
 72→        <Loading isFullScreen={false} />
 73→      </Screen>
 74→    );
 75→  }
 76→
 77→  return (
 78→    <Screen hideTopSafeArea>
 79→      <RoomHeader
 80→        room={room}
 81→        isMembersLoading={isMembersLoading}
 82→        roomMembers={roomMembers}
 83→        hasActiveCall={hasActiveCall ?? false}
 84→        hasNoCallOption={isRoomInvite || hasNoCallOption}
 85→        topInset={insets.top}
 86→        onBack={() => navigation.goBack()}
 87→        onRoomDetails={handleRoomDetails}
 88→        onStartCall={handleStartCall}
 89→      />
 90→
 91→      {isRoomInvite ? (
 92→        <RoomInvite
 93→          roomId={roomId}
 94→          roomInfo={roomInfo}
 95→          onAccepted={handleInviteAccepted}
 96→          onDeclined={handleInviteDeclined}
 97→        />
 98→      ) : (
 99→        <RoomTimeline room={room} roomId={roomId} />
100→      )}
101→    </Screen>
102→  );
103→};
