  1→import {
  2→  MembershipState_Tags,
  3→  type UserProfile,
  4→} from "@unomed/react-native-matrix-sdk";
  5→import { MatrixService } from "modules/matrix-client/services";
  6→import { type FC, useEffect, useMemo, useState } from "react";
  7→import { FlatList, Image, StyleSheet } from "react-native";
  8→import { Input, Loading } from "shared/components";
  9→import { Colors } from "shared/styles";
 10→import { ListItemPerson } from "../list-item-person";
 11→
 12→interface Props {
 13→  members: RoomMember[];
 14→  invitedPeople: UserProfile[];
 15→  setInvitedPeople: (invitedPeople: UserProfile[]) => void;
 16→}
 17→
 18→const shouldIgnoreUser = (tag: MembershipState_Tags) =>
 19→  tag === MembershipState_Tags.Join ||
 20→  tag === MembershipState_Tags.Invite ||
 21→  tag === MembershipState_Tags.Ban;
 22→
 23→export const PeopleSearch: FC<Props> = ({
 24→  members,
 25→  invitedPeople,
 26→  setInvitedPeople,
 27→}) => {
 28→  const [search, setSearch] = useState("");
 29→  const [loading, setLoading] = useState(false);
 30→  const [allPeople, setAllPeople] = useState<UserProfile[]>([]);
 31→  const listedPeople = useMemo(() => {
 32→    return [
 33→      ...invitedPeople,
 34→      ...allPeople.filter(
 35→        (p) =>
 36→          !invitedPeople.some((i) => i.userId === p.userId) &&
 37→          !members.some(
 38→            (m) => m.userId === p.userId && shouldIgnoreUser(m.membership?.tag),
 39→          ),
 40→      ),
 41→    ];
 42→  }, [invitedPeople, allPeople]);
 43→
 44→  useEffect(() => {
 45→    if (!search) {
 46→      setAllPeople([]);
 47→      return;
 48→    }
 49→
 50→    const timeoutId = setTimeout(async () => {
 51→      try {
 52→        setLoading(true);
 53→        const people = await MatrixService.searchUsers(search);
 54→        setAllPeople(people.results);
 55→      } catch (error) {
 56→        console.error(error);
 57→      } finally {
 58→        setLoading(false);
 59→      }
 60→    }, 350);
 61→
 62→    return () => clearTimeout(timeoutId);
 63→  }, [search]);
 64→
 65→  const handleInvitePerson = (p: UserProfile) => {
 66→    if (!invitedPeople.some((i) => i.userId === p.userId)) {
 67→      setInvitedPeople([...invitedPeople, p]);
 68→    } else {
 69→      setInvitedPeople(
 70→        invitedPeople.filter(
 71→          (invitedPerson) => invitedPerson.userId !== p.userId,
 72→        ),
 73→      );
 74→    }
 75→  };
 76→
 77→  return (
 78→    <>
 79→      <Input
 80→        placeholder="Search for someone"
 81→        value={search}
 82→        onChangeText={setSearch}
 83→        background={Colors.white10}
 84→        icon={
 85→          <Image
 86→            source={require("assets/icons/search.png")}
 87→            width={12}
 88→            height={12}
 89→            style={styles.icon}
 90→          />
 91→        }
 92→      />
 93→      <FlatList
 94→        contentContainerStyle={styles.list}
 95→        ListFooterComponent={() => {
 96→          if (loading) {
 97→            return <Loading text="Searching..." isFullScreen={false} />;
 98→          }
 99→
100→          return null;
101→        }}
102→        data={listedPeople}
103→        renderItem={({ item }) => (
104→          <ListItemPerson
105→            person={item}
106→            isSelected={invitedPeople.some(
107→              ({ userId }) => userId === item.userId,
108→            )}
109→            onPress={() => handleInvitePerson(item)}
110→          />
111→        )}
112→      />
113→    </>
114→  );
115→};
116→
117→const styles = StyleSheet.create({
118→  icon: {
119→    width: 12,
120→    height: 12,
121→  },
122→  list: {
123→    marginTop: 40,
124→    gap: 12,
125→    paddingBottom: 100,
126→  },
127→});
