  1→import { BottomSheetModal, BottomSheetScrollView } from "@gorhom/bottom-sheet";
  2→import {
  3→  animateSequence,
  4→  Block,
  5→  Text,
  6→  useAndroidBackHandler,
  7→} from "@prototyp/skeletor";
  8→import { MembershipState_Tags } from "@unomed/react-native-matrix-sdk";
  9→import { MatrixService } from "modules/matrix-client/services";
 10→import { NavigationContainerRef } from "modules/navigation/const";
 11→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 12→import { Alert, Dimensions, Image, StyleSheet } from "react-native";
 13→import Toast from "react-native-toast-message";
 14→import { Button, Loading } from "shared/components";
 15→import { UserImage } from "shared/components/user-image/UserImage";
 16→import { usePreventSwipeBack } from "shared/hooks";
 17→import { Colors, TextSize } from "shared/styles";
 18→
 19→const { height } = Dimensions.get("screen");
 20→
 21→interface Props {
 22→  isBottomSheetOpen: boolean;
 23→  selectedMember: MemberDetailsPayload | null;
 24→  roomId: string;
 25→  onClose: () => void;
 26→}
 27→
 28→export const MemberDetailsBottomSheet: React.FC<Props> = ({
 29→  isBottomSheetOpen,
 30→  selectedMember,
 31→  roomId,
 32→  onClose,
 33→}) => {
 34→  const ref = useRef<BottomSheetModal>(null);
 35→  const fadeIn = useRef(
 36→    animateSequence(
 37→      { opacity: [0, 1] },
 38→      {
 39→        duration: 200,
 40→      },
 41→    ),
 42→  ).current;
 43→  const [userPowerLevel, setUserPowerLevel] = useState<number | null>(null);
 44→  const [memberPowerLevel, setMemberPowerLevel] = useState<number | null>(null);
 45→  const isAdmin = useMemo(() => userPowerLevel === 100, [userPowerLevel]);
 46→  const isMemberAdmin = useMemo(
 47→    () => memberPowerLevel === 100,
 48→    [memberPowerLevel],
 49→  );
 50→  const isUser = useMemo(
 51→    () => selectedMember?.userId === MatrixService.instance?.userId(),
 52→    [selectedMember],
 53→  );
 54→  const isBanned = useMemo(
 55→    () => selectedMember?.membershipTag === MembershipState_Tags.Ban,
 56→    [selectedMember],
 57→  );
 58→  const [activeAction, setActiveAction] = useState<
 59→    "remove" | "ban" | "unban" | null
 60→  >(null);
 61→
 62→  const handleCloseBottomSheet = useCallback(() => {
 63→    fadeIn.reverse(() => onClose());
 64→  }, [fadeIn, onClose]);
 65→
 66→  const handleCloseBottomSheetOnPress = useCallback(() => {
 67→    handleCloseBottomSheet();
 68→    ref.current?.close();
 69→  }, [handleCloseBottomSheet]);
 70→
 71→  const handleViewProfile = useCallback(() => {
 72→    ref.current?.close();
 73→
 74→    if (isUser) {
 75→      NavigationContainerRef.navigate("userProfile");
 76→      return;
 77→    }
 78→    if (!selectedMember) return;
 79→
 80→    NavigationContainerRef.navigate("profile", {
 81→      userId: selectedMember.userId,
 82→    });
 83→  }, [isUser, selectedMember]);
 84→
 85→  const handleConfirmAction = useCallback(
 86→    async (action: "remove" | "ban" | "unban", reason: string) => {
 87→      if (!selectedMember) return;
 88→      try {
 89→        setActiveAction(action);
 90→        handleCloseBottomSheet();
 91→        ref.current?.close();
 92→
 93→        if (action === "ban") {
 94→          await MatrixService.banUserFromRoom(
 95→            roomId,
 96→            selectedMember.userId,
 97→            reason || undefined,
 98→          );
 99→        } else if (action === "unban") {
100→          await MatrixService.unbanUserFromRoom(
101→            roomId,
102→            selectedMember.userId,
103→            reason || undefined,
104→          );
105→        } else {
106→          await MatrixService.removeUserFromRoom(
107→            roomId,
108→            selectedMember.userId,
109→            reason || undefined,
110→          );
111→        }
112→
113→        Toast.show({
114→          type: "success",
115→          text1: `User ${action === "ban" ? "banned" : action === "unban" ? "unbanned" : "removed"} successfully`,
116→        });
117→        NavigationContainerRef.goBack();
118→      } catch (error) {
119→        console.error(`Failed to ${action} user:`, error);
120→        Toast.show({
121→          type: "error",
122→          text1: `Failed to ${action} user`,
123→        });
124→      } finally {
125→        setActiveAction(null);
126→      }
127→    },
128→    [selectedMember, roomId, handleCloseBottomSheet],
129→  );
130→
131→  const handleUserAction = useCallback(
132→    (action: "remove" | "ban" | "unban") => {
133→      if (!selectedMember) return;
134→
135→      const actionText = action === "ban" ? "banning" : "removing";
136→      const actionTitle = action === "ban" ? "Ban User" : "Remove User";
137→      const confirmButtonText =
138→        action === "ban" ? "Ban" : action === "unban" ? "Unban" : "Remove";
139→
140→      if (action === "unban") {
141→        Alert.alert(
142→          "Unban User",
143→          `Are you sure you want to unban ${selectedMember.displayName}?`,
144→          [
145→            {
146→              text: "Cancel",
147→              style: "cancel",
148→            },
149→            {
150→              text: "Unban",
151→              onPress: () => handleConfirmAction("unban", ""),
152→            },
153→          ],
154→        );
155→        return;
156→      }
157→
158→      Alert.prompt(
159→        actionTitle,
160→        `Enter a reason for ${actionText} ${selectedMember.displayName} (optional):`,
161→        [
162→          {
163→            text: "Cancel",
164→            style: "cancel",
165→          },
166→          {
167→            text: "Continue",
168→            onPress: (reason?: string) => {
169→              Alert.alert(
170→                "Are you sure?",
171→                `Are you sure you want to ${action} ${selectedMember.displayName} from this room?`,
172→                [
173→                  {
174→                    text: "Cancel",
175→                    style: "cancel",
176→                  },
177→                  {
178→                    text: confirmButtonText,
179→                    style: "destructive",
180→                    onPress: () => handleConfirmAction(action, reason || ""),
181→                  },
182→                ],
183→              );
184→            },
185→          },
186→        ],
187→        "plain-text",
188→      );
189→    },
190→    [selectedMember, handleConfirmAction],
191→  );
192→
193→  const handleRemoveUser = useCallback(
194→    () => handleUserAction("remove"),
195→    [handleUserAction],
196→  );
197→
198→  const handleBanUser = useCallback(
199→    () => handleUserAction("ban"),
200→    [handleUserAction],
201→  );
202→
203→  const handleUnbanUser = useCallback(
204→    () => handleUserAction("unban"),
205→    [handleUserAction],
206→  );
207→
208→  useAndroidBackHandler({
209→    handlePress: handleCloseBottomSheetOnPress,
210→    enabled: isBottomSheetOpen,
211→    disableDefault: isBottomSheetOpen,
212→  });
213→
214→  usePreventSwipeBack(isBottomSheetOpen);
215→
216→  useEffect(() => {
217→    if (!isBottomSheetOpen || !selectedMember) return;
218→    MatrixService.getUserPowerLevel(roomId)
