 26→/** Maximum age for a verification request to be considered valid (5 minutes) */
 27→const VERIFICATION_REQUEST_MAX_AGE_MS = 5 * 60 * 1000;
 28→
 29→/** Check if an event is a verification request */
 30→const isVerificationRequest = (event: EventTimelineItem): boolean => {
 31→  if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return false;
 32→  const kind = event.content.inner.content.kind;
 33→  if (kind?.tag !== MsgLikeKind_Tags.Message) return false;
 34→  const msgType = kind.inner.content.msgType;
 35→  return (
 36→    msgType?.tag === MessageType_Tags.Other &&
 37→    msgType.inner.msgtype === "m.key.verification.request"
 38→  );
 39→};
 40→
 41→/** Check if a verification request is recent enough to be handled */
 42→const isRecentVerificationRequest = (event: EventTimelineItem): boolean => {
 43→  const eventTimestamp = Number(event.timestamp);
 44→  const now = Date.now();
 45→  const age = now - eventTimestamp;
 46→  return age < VERIFICATION_REQUEST_MAX_AGE_MS;
 47→};
 48→
 49→interface Props {
 50→  room: RoomInterface | undefined;
 51→  roomId: string;
 52→}
 53→
 54→export const useRoomTimeline = ({ room, roomId }: Props) => {
 55→  const [events, setEvents] = useState<EventTimelineItem[]>([]);
 56→  const [loadingMessage, setLoadingMessage] = useState(true);
 57→  /** Track processed verification request IDs to avoid duplicates */
 58→  const processedVerificationRequestsRef = useRef<Set<string>>(new Set());
 59→  const [refreshing, setRefreshing] = useState(false);
 60→  const [updateTrigger, setUpdateTrigger] = useState(0);
 61→  const eventIdsRef = useRef<Set<string>>(new Set());
 62→  const timelineRef = useRef<TimelineInterface | null>(null);
 63→  const isPaginatingRef = useRef(false);
 64→  const timelinePaginateNumber = useRef<number>(20);
 65→  const setVerificationStatus = useSetAtom(MatrixAtoms.verificationStatus);
 66→  const setPinnedEventIds = useSetAtom(TimelineAtoms.pinnedEventIds);
 67→  const [isDirect, setIsDirect] = useState(false);
 68→
 69→  const upsertEvents = (
 70→    incoming: EventTimelineItem[],
 71→    position: "front" | "back" = "back",
 72→  ) => {
 73→    setEvents((prev) => {
 74→      const next = [...prev];
 75→      for (const e of incoming) {
 76→        const id = getEventId(e);
 77→        if (!id) continue;
 78→        const existingIndex = next.findIndex((item) => getEventId(item) === id);
 79→        if (existingIndex !== -1) {
 80→          next[existingIndex] = e;
 81→          continue;
 82→        }
 83→
 84→        eventIdsRef.current.add(id);
 85→        if (position === "front") next.unshift(e);
 86→        else next.push(e);
 87→      }
 88→      return next;
 89→    });
 90→  };
 91→
 92→  const handleVerificationRequest = (info: {
 93→    senderId: string;
 94→    flowId: string;
 95→  }) => {
 96→    setVerificationStatus("incomingRequest");
 97→    NavigationContainerRef.navigate("verifyUser", {
 98→      userId: info.senderId,
 99→      flowId: info.flowId,
100→    });
101→  };
102→
103→  const checkForVerificationRequests = useCallback(
104→    (incoming: EventTimelineItem[]) => {
105→      for (const event of incoming) {
106→        if (event.isOwn) continue;
107→
108→        if (
109→          !isVerificationRequest(event) ||
110→          !isRecentVerificationRequest(event)
111→        ) {
112→          continue;
113→        }
114→
115→        const flowId = getEventId(event);
116→        if (!flowId) continue;
117→
118→        if (processedVerificationRequestsRef.current.has(flowId)) continue;
119→
120→        processedVerificationRequestsRef.current.add(flowId);
121→
122→        handleVerificationRequest({
123→          senderId: event.sender,
124→          flowId,
125→        });
126→
127→        // Only handle one at a time
128→        break;
129→      }
130→    },
131→    [],
132→  );
133→
134→  const markAsRead = async () => {
135→    if (!room) return;
136→
137→    try {
138→      await room.markAsRead(ReceiptType.Read);
139→    } catch (error) {
140→      console.error("Failed to mark room as read:", error);
141→    }
142→  };
143→
144→  const loadMoreMessages = async () => {
145→    if (!room || !timelineRef.current) return;
146→
147→    isPaginatingRef.current = true;
148→    setRefreshing(true);
149→
150→    try {
151→      await timelineRef.current.paginateBackwards(
152→        timelinePaginateNumber.current,
153→      );
154→      timelinePaginateNumber.current += 20;
155→    } catch (error) {
156→      console.error("Failed to load more messages:", error);
157→    } finally {
158→      setRefreshing(false);
159→      isPaginatingRef.current = false;
160→    }
161→  };
162→
163→  useEffect(() => {
164→    if (!room) return;
165→    setPinnedEventIds([]);
166→    MatrixService.getPinnedEventIds(roomId)
167→      .then(setPinnedEventIds)
168→      .catch(console.error);
169→  }, [roomId]);
170→
171→  useEffect(() => {
172→    if (!room) return;
173→
174→    // Reset state when room changes
175→    setEvents([]);
176→    eventIdsRef.current.clear();
177→
178→    let timelineListenerHandle: TaskHandleInterface | null = null;
179→
180→    const initRoomTimeline = async () => {
181→      try {
182→        const timeline = await room.timelineWithConfiguration({
183→          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
184→          filter: new TimelineFilter.All(),
185→          internalIdPrefix: undefined,
186→          dateDividerMode: DateDividerMode.Daily,
187→          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
188→          reportUtds: false,
189→        });
190→
191→        // Store timeline in ref for reuse in pagination
192→        timelineRef.current = timeline;
193→
194→        await timeline.paginateBackwards(timelinePaginateNumber.current);
195→        timelinePaginateNumber.current += 20;
196→        setLoadingMessage(false);
197→
198→        // Set up timeline listener for real-time updates
199→        timelineListenerHandle = await timeline.addListener({
200→          onUpdate: (diffs) => {
201→            markAsRead();
202→            // Trigger re-render to update read receipts and other event properties
203→            setUpdateTrigger((prev) => prev + 1);
204→            diffs.forEach((diff) => {
205→              const change = diff.tag;
206→              switch (change) {
207→                case TimelineDiff_Tags.Append: {
208→                  const newItems = diff.inner.values;
209→                  if (newItems.length) {
210→                    const eventItems = newItems
211→                      .map((i) => i.asEvent())
212→                      .filter((i): i is EventTimelineItem => !!i);
213→
214→                    if (eventItems.length > 0) {
215→                      upsertEvents(eventItems, "back");
216→                      checkForVerificationRequests(eventItems);
217→                    }
218→                  }
219→                  break;
220→                }
221→                case TimelineDiff_Tags.Insert: {
222→                  const { value } = diff.inner;
223→                  const ev = value.asEvent();
224→                  if (ev) {
225→                    upsertEvents([ev], "back");
226→                    checkForVerificationRequests([ev]);
227→                  }
228→                  break;
229→                }
230→                case TimelineDiff_Tags.Set: {
231→                  const { value } = diff.inner;
232→                  const ev = value.asEvent();
233→                  if (ev) {
234→                    const id = getEventId(ev);
235→                    if (!id) break;
236→
237→                    setEvents((prev) => {
238→                      // Find event by ID to handle edits/deletions properly
239→                      const existingIndex = prev.findIndex(
240→                        (e) => getEventId(e) === id,
241→                      );
242→                      if (existingIndex !== -1) {
243→                        const next = [...prev];
244→                        next[existingIndex] = ev;
245→                        return next;
246→                      }
247→                      // If not found and not tracked, add it
248→                      if (!eventIdsRef.current.has(id)) {
249→                        eventIdsRef.current.add(id);
250→                        return [...prev, ev];
251→                      }
252→                      return prev;
253→                    });
254→                  }
255→                  break;
256→                }
257→                case TimelineDiff_Tags.Remove: {
258→                  const { index: removeIndex } = diff.inner;
259→                  setEvents((prev) => {
260→                    const next = prev.filter((_, idx) => idx !== removeIndex);
261→                    eventIdsRef.current = new Set(
262→                      next.map(getEventId).filter(Boolean) as string[],
263→                    );
264→                    return next;
265→                  });
266→                  break;
267→                }
268→                case TimelineDiff_Tags.PushFront: {
269→                  const { value } = diff.inner;
270→                  const ev = value.asEvent();
271→                  if (ev) {
272→                    upsertEvents([ev], "front");
273→                    checkForVerificationRequests([ev]);
274→                  }
275→                  break;
276→                }
277→                case TimelineDiff_Tags.PushBack: {
278→                  const { value } = diff.inner;
279→                  const ev = value.asEvent();
280→                  if (ev) {
281→                    upsertEvents([ev], "back");
282→                    checkForVerificationRequests([ev]);
283→                  }
284→                  break;
285→                }
286→                case TimelineDiff_Tags.Reset: {
287→                  const resetItems = diff.inner.values;
288→                  if (resetItems.length) {
289→                    const eventItems = resetItems
290→                      .map((i) => i.asEvent())
291→                      .filter((i): i is EventTimelineItem => !!i);
292→
293→                    // Deduplicate events in case Reset contains duplicates
294→                    const seenIds = new Set<string>();
295→                    const uniqueEvents: EventTimelineItem[] = [];
296→
297→                    for (const event of eventItems) {
298→                      const id = getEventId(event);
299→                      if (id && !seenIds.has(id)) {
300→                        seenIds.add(id);
301→                        uniqueEvents.push(event);
302→                      }
303→                    }
304→
305→                    eventIdsRef.current = seenIds;
306→                    setEvents(uniqueEvents);
307→                  }
308→                  break;
309→                }
310→                case TimelineDiff_Tags.Truncate: {
311→                  const { length: cut } = diff.inner;
312→                  setEvents((prev) => {
313→                    const next = prev.slice(0, cut);
314→                    eventIdsRef.current = new Set(
315→                      next.map(getEventId).filter(Boolean) as string[],
316→                    );
317→                    return next;
318→                  });
319→                  break;
320→                }
321→                default:
322→                  console.log("Unknown timeline change type:", change);
323→              }
324→            });
325→          },
326→        });
327→      } catch (error) {
328→        console.error("Failed to initialize room timeline:", error);
329→        return null;
330→      }
331→    };
332→
333→    initRoomTimeline();
334→
335→    return () => {
336→      timelineListenerHandle?.cancel?.();
337→      timelineRef.current = null;
338→    };
339→  }, [roomId, checkForVerificationRequests]);
340→
341→  useEffect(() => {
342→    markAsRead().catch(console.error);
343→    room?.isDirect().then(setIsDirect).catch(console.error);
344→  }, []);
345→
346→  return {
347→    events,
348→    loadingMessage,
349→    refreshing,
350→    timelineRef,
351→    isPaginatingRef,
352→    updateTrigger,
353→    isDirect,
354→    loadMoreMessages,
355→    markAsRead,
356→  };
357→};
